WITH exploded AS (SELECT id, plan, effective_from, currency, tier_value FROM price_tiers LATERAL VIEW OUTER EXPLODE(tier_prices) e AS tier_value) SELECT CASE WHEN tier_value >= 79 THEN 'PREMIUM' ELSE 'STANDARD' END AS tier_value_tier, COUNT_IF(currency = 'EUR') AS eur_events, COUNT(*) FILTER (WHERE currency = 'USD') AS usd_rows FROM exploded GROUP BY CASE WHEN tier_value >= 79 THEN 'PREMIUM' ELSE 'STANDARD' END;
